//
//  ProjectImageEncoder.swift
//  BeadInventory
//
//  用户图片（图纸 thumbnail / 成品图 finishedImage）落盘前的统一编码器。
//
//  ## 为什么需要它
//
//  拼图模式的引入（`730cd29`）把三个图片写入点从「200×200 JPEG 0.6」一次性改成了
//  `pngData()`。commit message 原话是「两处都改为 pngData() 无损存储」。这里面其实是
//  **两件事被捆在一起**：
//
//      分辨率  200×200      →  全分辨率      ← 对的，拼图模式确实需要（200px 采样不了 100×100 网格）
//      编码    JPEG 0.6     →  PNG 无损      ← 纯浪费
//
//  **照片型** 2400px 图，PNG ≈ 13 MB，重编码后 ≈ 1.5 MB —— 分辨率一个像素没少
//  （真机实测 12,975,516 B → 1,560,605 B）。纯色块图纸相反，PNG 本来就小，见下面「编码策略」。
//  这一个数量级正是把 SQLite 库撑到 GB 级的原因：
//
//    - `thumbnail` / `finishedImage` / `displayThumbnail` 都是 **inline BLOB**。
//      SQLite 改任何一列都要重写整条记录（含全部 overflow page）。往一条内联着 13 MB
//      原图的行里写 100 KB 的 `displayThumbnail`，实际写盘就是 13 MB。
//      458 项目 ≈ 6 GB，加 WAL + checkpoint = 用户 IPS 里那 68.72 GB dirty writes。
//    - 库涨到 GB 级之后，CoreData+CloudKit 的
//      `_performPostSaveTasks:andForceFullVacuum:` / `sqlite3_wal_checkpoint_v2`
//      会持 EXCLUSIVE 锁数十秒，撞上首屏那次 fetch → `0x8BADF00D` scene-create 看门狗。
//
//  所以本编码器只做一件事：**把无损那半撤回，分辨率那半原样保留**。
//
//  ## 对拼图模式的影响（已逐条核对，不是估计）
//
//  - `BeadPatternGrid.corners` 是**归一化 0-1** 坐标（见 `GridGeometry.denormalize`），
//    只要宽高比不变，重编码后现有网格标定完全不受影响，不需要任何坐标迁移。
//  - `GridCellSampler` 每格取 8 个采样点（0.2/0.5/0.8 三档，**避开格边和中心文字**），
//    **每点各自做 ΔE ≤ 30 匹配再投票，需 ≥2 票才判定色号**。JPEG 的 ringing 集中在色块
//    边界，正是被 8 点布局避开的位置；即使个别点被污染，2/8 的投票门槛也会把它吸收掉。
//    （平均 Lab 只喂 near-white 预过滤，不参与色号判定 —— 别把它当成抗噪机制。）
//  - `GridCellSampler` 里 near-white 预过滤的注释本来就写着「图纸背景常带轻微色偏
//    （JPEG 压缩、屏幕色温等）」—— 采样链路本就是按「输入带 JPEG 色偏」设计的。
//
//  ## 编码策略
//
//  1. 超过 `maxPixelSize` 的图先降到 `maxPixelSize`（防御 8000px 这种病态输入；
//     用户实测数据是 2400px 左右，绝大多数图走不到这一步，分辨率原样保留）。
//  2. **PNG 永远先试**。进预算就用 PNG —— 纯色块合成图纸（拼豆图纸最常见的形态）
//     PNG 压得极好，2400px 的 100×100 色块图只有 228 KB，而同一张 JPEG 0.92 反而要
//     1.05 MB（DCT 最不擅长锐利色块边界）。无脑上 JPEG 会把这批用户的图放大 4-5 倍。
//  3. PNG 超预算且**真的没有透明像素** → 再试 JPEG，质量 0.92 起。
//     注意判据是「有没有透明**像素**」而不是「有没有 alpha 通道」——
//     裁剪 / 方向归一化的渲染产物几乎总是带 alpha 通道但完全不透明，
//     早期实现在这里判错，让相机照片全部退化成 PNG-only（见 `containsTransparency`）。
//  4. 仍超预算就沿 `pixelSizeSteps`（外层）× `qualitySteps`（内层）逐档退让，
//     直到进预算或触底（`minPixelSize`）。触底仍超预算就接受 —— 宁可留一张大图，
//     也不把用户的图纸糊到不能用。
//
//  ## 线程
//
//  全部 `nonisolated`，可以从任意后台 Task 调用。迁移器就是在后台 executor 上直接同步调。

import Foundation
import UIKit
import ImageIO

enum ProjectImageEncoder {

    /// 输出最长边上限。2400px 是实测用户数据的典型值，3072 留一档余量：
    /// 常规图片走不到这条线，分辨率原样保留；只有病态大图（8000px 扫描件）才会被降。
    static let maxPixelSize: Int = 3072

    /// 单张图的目标字节预算。照片型 2400px 图重编码实测落在 1.4-1.6 MB（噪声越强 DCT 越压不动），
    /// 纯色块图纸则远低于此。**预算是 best-effort 目标，不是保证** —— 触底仍超预算会被接受，
    /// 真正的硬约束是 `compactionThresholdBytes`。
    static let targetByteBudget: Int = 1_200_000

    /// 退让的下限 —— 再小就影响拼图模式网格识别了（100×100 网格 @ 1600px = 16px/格，
    /// 采样点间距 ~5px，仍然够用；再往下 8px/格 时 0.2/0.8 两档采样点会挤到格边上）。
    static let minPixelSize: Int = 1600

    /// 超过这个字节数就认为「这张图该被重编码」。迁移扫描器用它筛选候选行。
    ///
    /// 取 `targetByteBudget` 的 ~1.7 倍，让正常编码结果稳定落在阈值下方，绝大多数行一轮收敛。
    /// **但这不是结构性保证** —— `encodeCGImage` 在触底仍超预算时照样返回结果，
    /// `recompressInner` 只要比源小就接受。真正兜底终止的是两层记账：
    /// 本轮靠协调器的 `excluded` 集合，跨启动靠 `.stubborn` 落盘（见
    /// `ThumbnailMigrationCoordinator`）。
    static let compactionThresholdBytes: Int = 2_000_000

    private static let qualitySteps: [CGFloat] = [0.92, 0.85, 0.78]
    private static let pixelSizeSteps: [Int] = [maxPixelSize, 2400, 2000, minPixelSize]

    /// 编码结果。
    ///
    /// `didReachBudget` / `usedLossless` / `pixelSize` 三个字段**仅供诊断与测试**，
    /// 不要拿它们做控制流：`didReachBudget` 量的是 `targetByteBudget`（1.2 MB），
    /// 而迁移器关心的收敛问题量的是 `compactionThresholdBytes`（2 MB），两者不是一回事。
    /// 迁移器判断「还要不要再管这一行」应该直接比 `data.count` 与阈值。
    struct EncodeResult: Sendable {
        let data: Data
        let didReachBudget: Bool
        let usedLossless: Bool
        let pixelSize: CGSize
    }

    // MARK: - 写入路径（UIImage → Data）

    /// 用户在 App 里选好图、准备落盘时调用（ScanView / ProjectImageEditorSheet /
    /// Share Extension）。替代原来的裸 `image.pngData()`。
    static nonisolated func encode(_ image: UIImage) -> Data? {
        encodeResult(image)?.data
    }

    static nonisolated func encodeResult(_ image: UIImage) -> EncodeResult? {
        guard let cg = image.cgImage else {
            // CIImage-backed UIImage（滤镜产物）没有 cgImage。走 renderer 兜底：
            // 按原尺寸渲一遍拿到位图，再进正常流程。
            // 源信息全丢了，只能保守当作带 alpha。
            guard let rendered = renderToCGImage(image, maxPixelSize: maxPixelSize, hasAlpha: true) else {
                AppLogger.shared.error("ProjectImageEncoder", "no_cgimage", metadata: [
                    "size": "\(image.size)"
                ])
                return nil
            }
            return encodeCGImage(rendered, hasAlpha: containsTransparency(rendered))
        }

        // **alpha 必须取自源图，不能取自渲染产物。**
        //
        // 这里踩过一个会让整个修复失效的坑：`renderToCGImage` 原本硬编码
        // `format.opaque = false`，产物一律带 alpha 通道（premultipliedFirst）。而
        // `attempt` 里带 alpha 就禁用 JPEG 分支（JPEG 无 alpha），于是**任何 orientation
        // 不是 .up 的图都只剩 PNG 阶梯，永远进不了预算**。
        //
        // 而 iPhone 相机照片的 orientation 就是 `.right` —— 也就是最常见的输入路径。
        // 实测同一张 2400px 噪声图：
        //     .up      → 1,429,323 B (JPEG)
        //     .right   → 4,318,567 B (PNG)   ← 3 倍大，且高于 compactionThresholdBytes
        // 高于扫描阈值意味着这类行**永远不收敛**，迁移器每轮都会重新选中它。
        // 裁剪路径同理（`ImageCropView.normalizeImageOrientation` 也是 opaque: false）。
        let sourceHasAlpha = containsTransparency(cg)

        // UIImage 的 orientation 必须在这里烘进位图 —— 否则 JPEG 靠 EXIF 记方向，
        // 而 `GridCellSampler` 直接吃 `UIImage.cgImage` 的裸像素（不看 orientation），
        // 拼图模式的网格会跟图对不上。
        let oriented: CGImage
        if image.imageOrientation == .up {
            oriented = cg
        } else {
            guard let r = renderToCGImage(image, maxPixelSize: maxPixelSize, hasAlpha: sourceHasAlpha) else {
                // 这条路径以前静默返 nil —— 而调用方把 nil 当成「用户要删图」，
                // 会把现存照片清掉（见 ProjectDetailView 的 guard）。至少要可观测。
                AppLogger.shared.error("ProjectImageEncoder", "orientation_render_failed", metadata: [
                    "size": "\(image.size)",
                    "orientation": "\(image.imageOrientation.rawValue)"
                ])
                return nil
            }
            oriented = r
        }
        return encodeCGImage(oriented, hasAlpha: sourceHasAlpha)
    }

    // MARK: - 迁移路径（Data → Data）

    /// 已落盘的老图重编码。返回 nil 表示「不需要动」或「动不了」，调用方应保持原样。
    ///
    /// 内存边界：用 `CGImageSourceCreateThumbnailAtIndex` 直接在 source 层出目标尺寸位图，
    /// **不走 `UIImage(data:)` 的全分辨率解码**（13 MB PNG → 全解码是 ~30-60 MB UIImage，
    /// 正是 458 项目用户 jetsam 的老路）。峰值 ≈ 3072² × 4 ≈ 37 MB，迁移器一次只处理一张。
    ///
    /// - Parameter source: 库里现存的字节
    /// - Returns: 更小的新字节；已经够小 / 解不开 / 重编码后反而更大 → nil
    static nonisolated func recompress(_ source: Data) -> EncodeResult? {
        // **必须显式 autoreleasepool。**
        //
        // 这条路径要解一张全分辨率位图（3072×2304×4 ≈ 28 MB）并试多种编码，中间产物
        // （CGImage / UIImage / 每次 encode 出来的 Data）全是 autorelease 的。
        // 迁移器是在一个长跑的 async 循环里逐条调用它，Swift 并发的隐式 pool 不会在
        // 循环中间排空 —— 实测 24 条连续瘦身，进程 footprint 涨了 **935 MB**
        // （StoreCompactionIntegrationTests 抓到的）。真机上这就是 jetsam：
        // 修崩溃的迁移器自己把 App 干掉，与 round-10 那次「修 jetsam 的协调器自己撞 jetsam」
        // 是同一个形状。
        //
        // 加了 pool 之后每条处理完立即归还，峰值恒定为一张图。
        var result: EncodeResult?
        autoreleasepool {
            result = recompressInner(source)
        }
        return result
    }

    private static nonisolated func recompressInner(_ source: Data) -> EncodeResult? {
        guard source.count > compactionThresholdBytes else { return nil }

        let sourceOptions: [CFString: Any] = [kCGImageSourceShouldCache: false]
        guard let imageSource = CGImageSourceCreateWithData(source as CFData, sourceOptions as CFDictionary) else {
            AppLogger.shared.error("ProjectImageEncoder", "recompress_create_source_failed", metadata: [
                "sourceBytes": source.count
            ])
            return nil
        }

        let thumbnailOptions: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,   // 烘进 EXIF 方向，理由同 encodeResult
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ]
        guard let decoded = CGImageSourceCreateThumbnailAtIndex(imageSource, 0, thumbnailOptions as CFDictionary) else {
            AppLogger.shared.error("ProjectImageEncoder", "recompress_decode_failed", metadata: [
                "sourceBytes": source.count
            ])
            return nil
        }

        // 透明度以**解码出来的位图**为准，不看 `kCGImagePropertyHasAlpha` ——
        // 那个属性报的同样是「有没有 alpha 通道」，对我们自己早期版本落盘的
        // RGBA PNG 一律为 true，会把整批老数据锁死在 PNG-only 路径上。
        guard let result = encodeCGImage(decoded, hasAlpha: containsTransparency(decoded)) else { return nil }

        // 重编码后反而更大（源本来就是高效编码的小图，只是像素多）—— 保持原样更好。
        guard result.data.count < source.count else {
            AppLogger.shared.info("ProjectImageEncoder", "recompress_not_beneficial", metadata: [
                "sourceBytes": source.count,
                "encodedBytes": result.data.count
            ])
            return nil
        }
        return result
    }

    // MARK: - 内部

    private static nonisolated func encodeCGImage(_ image: CGImage, hasAlpha: Bool) -> EncodeResult? {
        var lastAttempt: EncodeResult?
        let longestEdge = max(image.width, image.height)
        guard longestEdge > 0 else { return nil }

        // 每一档的**实际**输出边长是 min(原图边长, 档位)。原图比某档小时该档退化成「不缩放」，
        // 跟前一档结果相同 —— 用 triedEdges 去重，避免对同一尺寸重复编码烧 CPU。
        // （早期写法在这里 `break`，导致 2400px 的图永远试不到 2000/1600 两档退让。）
        var triedEdges = Set<Int>()

        for pixelSize in pixelSizeSteps {
            let effectiveEdge = min(longestEdge, pixelSize)
            guard triedEdges.insert(effectiveEdge).inserted else { continue }

            // 每一档单独 pool：一档要试 PNG + 三档 JPEG 质量，四份 Data 全是 autorelease 的，
            // 不当场归还的话「试探性编码」的中间产物会全程堆着。
            var settled: EncodeResult?
            autoreleasepool {
                settled = attempt(image: image, edge: effectiveEdge, longestEdge: longestEdge,
                                  hasAlpha: hasAlpha, best: &lastAttempt)
            }
            if let settled { return settled }
        }

        if let lastAttempt {
            AppLogger.shared.info("ProjectImageEncoder", "budget_not_reached", metadata: [
                "bytes": lastAttempt.data.count,
                "budget": targetByteBudget,
                "lossless": lastAttempt.usedLossless,
                "pixelSize": "\(lastAttempt.pixelSize)"
            ])
        } else {
            AppLogger.shared.error("ProjectImageEncoder", "encode_produced_nothing", metadata: [
                "width": image.width,
                "height": image.height,
                "hasAlpha": hasAlpha
            ])
        }
        return lastAttempt
    }

    /// 单个尺寸档位的尝试。进预算就返回结果；否则把「目前最小的一版」记进 `best` 返回 nil。
    private static nonisolated func attempt(
        image: CGImage,
        edge: Int,
        longestEdge: Int,
        hasAlpha: Bool,
        best lastAttempt: inout EncodeResult?
    ) -> EncodeResult? {
        let scaled: CGImage
        if edge == longestEdge {
            scaled = image                                  // 不缩放，分辨率原样保留
        } else {
            guard let s = resize(image, maxPixelSize: edge) else { return nil }
            scaled = s
        }

        let size = CGSize(width: scaled.width, height: scaled.height)
        let ui = UIImage(cgImage: scaled)

        // **先试 PNG，够小就用 PNG。**
        //
        // 这不是保守，是实测结论：纯色块合成图纸（拼豆图纸最常见的形态）PNG 压得极好 ——
        // 2400px 的 100×100 色块图 PNG 只有 228 KB，而同一张图 JPEG 0.92 反而要 1.05 MB
        // （JPEG 的 DCT 最不擅长处理锐利色块边界，网格线更是每条都要花码率）。
        // 早期版本无脑上 JPEG，会把这批用户的图从 228 KB 放大到 1 MB —— 修崩溃的过程中
        // 把一部分人搞得更糟。
        //
        // 真正撑爆库的 13 MB 图是**照片型**内容（2400px / 13MB ≈ 2.2 字节每像素，
        // 纯色块图不可能到这个密度），那类图 PNG 压不动、JPEG 一压就下来，走下面的分支。
        if let png = ui.pngData() {
            let result = EncodeResult(data: png, didReachBudget: png.count <= targetByteBudget,
                                      usedLossless: true, pixelSize: size)
            if result.didReachBudget { return result }
            lastAttempt = smaller(lastAttempt, result)
        }

        // 带 alpha 不能转 JPEG（无 alpha 通道，压平到白底会在深色模式下露馅），
        // 只能靠降分辨率继续退让。
        guard !hasAlpha else { return nil }

        for quality in qualitySteps {
            guard let jpeg = ui.jpegData(compressionQuality: quality) else { continue }
            let result = EncodeResult(data: jpeg, didReachBudget: jpeg.count <= targetByteBudget,
                                      usedLossless: false, pixelSize: size)
            if result.didReachBudget { return result }
            lastAttempt = smaller(lastAttempt, result)
        }
        return nil
    }

    private static nonisolated func smaller(_ a: EncodeResult?, _ b: EncodeResult) -> EncodeResult {
        guard let a else { return b }
        return b.data.count < a.data.count ? b : a
    }

    /// 图里**是否真的有透明像素** —— 不是「有没有 alpha 通道」。
    ///
    /// 这个区分是 C1 的核心。带 alpha 通道的图绝大多数是完全不透明的：
    /// `UIGraphicsImageRenderer` 只要 `opaque == false` 就输出 `premultipliedFirst`，
    /// 而裁剪（`ImageCropView.normalizeImageOrientation`）和方向归一化都走它。
    /// 早期实现拿「有 alpha 通道」当「有透明度」来禁用 JPEG，结果是**裁剪过或旋转过的
    /// 照片全部退化成 PNG-only**，压不到阈值下方、迁移永不收敛 —— 实测一张裁剪过的
    /// 2400px 照片输出 5,840,831 B。
    ///
    /// 判定成本：先看 alphaInfo 快速否定（没通道就不可能透明）；有通道时才把 alpha
    /// 通道单独渲染出来扫一遍。渲染上限压到 1024px（~1 MB 缓冲）—— 真正的透明图纸
    /// 都是大片透明区域，降采样后依然可见；代价是可能漏掉零星几个像素的透明度，
    /// 那种情况压平成白底在视觉上也无差别。
    ///
    /// 任何一步失败都保守返回 `true`（走无损），宁可图大一点也不能把用户的透明图压平。
    private static nonisolated func containsTransparency(_ image: CGImage) -> Bool {
        switch image.alphaInfo {
        case .none, .noneSkipFirst, .noneSkipLast:
            return false                      // 没有 alpha 通道，不可能有透明像素
        case .first, .last, .premultipliedFirst, .premultipliedLast, .alphaOnly:
            break                             // 有通道，得看实际像素
        @unknown default:
            return true                       // 不认识的形态，保守
        }

        let maxScanEdge = 1024
        let longest = max(image.width, image.height)
        let scale = longest > maxScanEdge ? Double(maxScanEdge) / Double(longest) : 1
        let w = max(1, Int((Double(image.width) * scale).rounded()))
        let h = max(1, Int((Double(image.height) * scale).rounded()))

        // **缓冲必须清零，不能预填 255。**
        //
        // `CGContext.draw` 是 source-over 合成，不是 copy。目标预填 255（alpha=1.0）时
        //     dst = src + 1·(1 − src) = 1
        // 恒等于不透明 —— 函数结构上不可能返回 true，任何透明图都会被判成不透明，
        // 进而被 JPEG 压平。实测：4.8 MB 的半透明图 → usedLossless=false，
        // 解码回来 alphaInfo=noneSkipFirst，**透明度被永久摧毁**。
        //
        // 这比它要修的原 bug 更糟：原 bug 只是图偏大，这个是不可逆地毁用户数据，
        // 而且迁移器会在后台自动对存量图执行。
        //
        // 清零之后 source-over 得到 dst = src，即真实 alpha；而且「画不上去」
        // （draw 无效）也会留下 0 → 报告有透明 → 走无损，方向仍然是保守的。
        var buffer = [UInt8](repeating: 0, count: w * h)
        let rendered = buffer.withUnsafeMutableBytes { raw -> Bool in
            guard let ctx = CGContext(
                data: raw.baseAddress, width: w, height: h,
                bitsPerComponent: 8, bytesPerRow: w,
                space: CGColorSpaceCreateDeviceGray(),
                bitmapInfo: CGImageAlphaInfo.alphaOnly.rawValue
            ) else { return false }
            ctx.draw(image, in: CGRect(x: 0, y: 0, width: w, height: h))
            return true
        }
        guard rendered else {
            AppLogger.shared.error("ProjectImageEncoder", "alpha_scan_failed", metadata: [
                "width": image.width, "height": image.height
            ])
            return true
        }
        return buffer.contains { $0 < 255 }
    }

    private static nonisolated func resize(_ image: CGImage, maxPixelSize: Int) -> CGImage? {
        let longestEdge = max(image.width, image.height)
        guard longestEdge > maxPixelSize else { return image }
        let scale = CGFloat(maxPixelSize) / CGFloat(longestEdge)
        let target = CGSize(width: (CGFloat(image.width) * scale).rounded(),
                            height: (CGFloat(image.height) * scale).rounded())
        let format = UIGraphicsImageRendererFormat.preferred()
        format.scale = 1            // 按像素画，不要乘设备 scale
        format.opaque = !containsTransparency(image)
        let renderer = UIGraphicsImageRenderer(size: target, format: format)
        let ui = renderer.image { _ in
            UIImage(cgImage: image).draw(in: CGRect(origin: .zero, size: target))
        }
        return ui.cgImage
    }

    /// UIImage → 已应用 orientation 的 CGImage（顺带做上限降采样）。
    ///
    /// `hasAlpha` 必须由调用方按**源图**传入：渲染器的 `opaque` 决定产物有没有 alpha 通道，
    /// 而下游拿 alpha 通道当「有透明度」用来禁用 JPEG。硬编码 false 会让所有旋转过的
    /// 照片（相机图就是 `.right`）退化成 PNG-only，见 `encodeResult` 里的详细说明。
    private static nonisolated func renderToCGImage(
        _ image: UIImage,
        maxPixelSize: Int,
        hasAlpha: Bool
    ) -> CGImage? {
        let longestEdge = max(image.size.width, image.size.height)
        guard longestEdge > 0 else { return nil }
        let scale = min(CGFloat(maxPixelSize) / longestEdge, 1.0)
        let target = CGSize(width: (image.size.width * scale).rounded(),
                            height: (image.size.height * scale).rounded())
        let format = UIGraphicsImageRendererFormat.preferred()
        format.scale = 1
        format.opaque = !hasAlpha
        let renderer = UIGraphicsImageRenderer(size: target, format: format)
        // renderer.image 内部 draw 会应用 UIImage.imageOrientation
        return renderer.image { _ in
            image.draw(in: CGRect(origin: .zero, size: target))
        }.cgImage
    }
}

//
//  ImageDownsampler.swift
//  BeadInventory
//
//  原图 → 小缩略图的 downsample 工具。供 displayThumbnail 字段生成 + 列表 row
//  在 displayThumbnail 缺失时的 fallback 解码使用。
//
//  设计要点：
//  - 用 ImageIO `CGImageSourceCreateThumbnailAtIndex` 而不是 UIImage(data:) + resize：
//    前者在 CGImageSource 内部直接生成目标尺寸位图，跳过全分辨率解码 → 内存峰值 KB 级
//    而不是 MB 级；后者会把原图先解码出来（30+ MB），背道而驰。
//  - `kCGImageSourceCreateThumbnailFromImageAlways = true` 强制生成（即使源图无 EXIF
//    thumbnail），`shouldCacheImmediately = true` 把解码挪到这里完成（而不是后续 draw time
//    在主线程上发生）。
//  - 输出 JPEG @ 0.85：经验值 —— 拼豆图大多色块密集，JPEG 0.85 几乎看不出退化，
//    单图通常 30-100 KB（vs 原 PNG 几 MB）。0.9 大小翻倍，0.8 开始能看到色块边缘 artifact。
//  - 标记 `nonisolated` —— 调用方可以从任意 Task / 后台 actor 调用，不必跳主线程。
//
//  错误处理：失败时返回 nil + logError 一条诊断。调用方需要兜底 ——
//  **写入 displayThumbnail = nil**（清空），让 `ProjectThumbnailImage` 走第二优先级
//  fallback（CGImageSourceCreateThumbnailAtIndex 实时 downsample）兜底。
//  Round-4 曾把"用原 thumbnail 字节兜底"，但那会让列表 row 通过 `UIImage(data:)` 解码 5-10 MB
//  PNG 重蹈 jetsam —— round-5 F1 改回 nil。

import Foundation
import UIKit
import ImageIO

enum ImageDownsampler {

    /// downsample 输出目标：512px 以内的最大边 + JPEG 0.85。
    /// 数字经过测算：列表 row 在 3x 设备上不超过 120pt，512px 已经远超显示需求 + 留出
    /// 用户从列表点开后的瞬间放大缓冲。再大就接近原图，没有压缩意义。
    static let defaultMaxPixelSize: Int = 512
    static let defaultJPEGQuality: CGFloat = 0.85

    /// 把 PNG / JPEG 原图字节降采样成小缩略图。
    ///
    /// - Parameters:
    ///   - sourceData: 原图字节（PNG/JPEG，任意尺寸）
    ///   - maxPixelSize: 输出最大边长（默认 512px）
    ///   - jpegQuality: JPEG 输出质量（默认 0.85）
    /// - Returns: JPEG 字节；失败返回 nil（不抛 throw，避免把"用户图坏了/格式特别"误升级成错误流）
    static nonisolated func downsample(
        _ sourceData: Data,
        maxPixelSize: Int = defaultMaxPixelSize,
        jpegQuality: CGFloat = defaultJPEGQuality
    ) -> Data? {
        // 用 ImageIO 不走 UIImage —— UIImage(data:) 会先解码全分辨率，内存峰值会到原图
        // RGBA × pixel 数（5MB PNG → ~30MB UIImage）。CGImageSource 直接出小图，峰值 KB 级。
        let sourceOptions: [CFString: Any] = [
            kCGImageSourceShouldCache: false  // 不缓存源图全分辨率
        ]
        guard let source = CGImageSourceCreateWithData(sourceData as CFData, sourceOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_source_failed", metadata: [
                "bytes": sourceData.count
            ])
            return nil
        }

        let thumbnailOptions: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,  // 应用 EXIF 方向
            kCGImageSourceShouldCacheImmediately: true,         // 解码在这里完成
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ]
        guard let cgThumb = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_thumbnail_failed", metadata: [
                "bytes": sourceData.count,
                "maxPixelSize": maxPixelSize
            ])
            return nil
        }

        let uiThumb = UIImage(cgImage: cgThumb)
        guard let jpeg = uiThumb.jpegData(compressionQuality: jpegQuality) else {
            AppLogger.shared.error("ImageDownsampler", "jpeg_encode_failed", metadata: [
                "bytes": sourceData.count,
                "thumbWidth": cgThumb.width,
                "thumbHeight": cgThumb.height
            ])
            return nil
        }
        return jpeg
    }

    /// 跟 downsample 一样，但返回 UIImage 而不是字节 —— 给「列表 row 没有 displayThumbnail
    /// 时直接用 fallback 显示」的路径用，省一次 JPEG encode + decode round-trip。
    ///
    /// 注意：返回的 UIImage 已经预解码（kCGImageSourceShouldCacheImmediately），
    /// 上屏不会再触发主线程 decode。
    static nonisolated func downsampleToUIImage(
        _ sourceData: Data,
        maxPixelSize: Int = defaultMaxPixelSize
    ) -> UIImage? {
        let sourceOptions: [CFString: Any] = [
            kCGImageSourceShouldCache: false
        ]
        guard let source = CGImageSourceCreateWithData(sourceData as CFData, sourceOptions as CFDictionary) else {
            // **round-10 review Nit**：之前两个失败点都静默返 nil，跟兄弟 method `downsample`
            // 不对称。这条路径是老用户没有 displayThumbnail 时列表 row 的兜底降级 ——
            // 如果某些畸形 PNG / 损坏字节让 CGImageSource 创建失败，用户看到列表里那个 row
            // 永远是 placeholder，Sentry 抓不到 → 调查无从下手。补 logError 让监控可观测。
            AppLogger.shared.error("ImageDownsampler", "create_source_failed_uimage_path", metadata: [
                "sourceBytes": sourceData.count
            ])
            return nil
        }
        let thumbnailOptions: [CFString: Any] = [
            kCGImageSourceCreateThumbnailFromImageAlways: true,
            kCGImageSourceCreateThumbnailWithTransform: true,
            kCGImageSourceShouldCacheImmediately: true,
            kCGImageSourceThumbnailMaxPixelSize: maxPixelSize
        ]
        guard let cgThumb = CGImageSourceCreateThumbnailAtIndex(source, 0, thumbnailOptions as CFDictionary) else {
            AppLogger.shared.error("ImageDownsampler", "create_thumbnail_failed_uimage_path", metadata: [
                "sourceBytes": sourceData.count,
                "maxPixelSize": maxPixelSize
            ])
            return nil
        }
        return UIImage(cgImage: cgThumb)
    }

    // 注：原先有 `migrationThresholdBytes = 200_000` —— round-5 N1 后已弃用
    //（一张 199 KB 的 4000×4000 PNG 仍能 UIImage(data:) 解码爆 60MB，所以 migration 不能因
    // "字节小"就跳过 downsample）。常量已删除，避免给未来维护者错误信号。
}

//
//  ProjectImageLoader.swift
//  BeadInventory
//
//  列表 / 日历 / 详情页取图的**后台**入口。
//
//  ## 它修的是哪一条崩溃栈
//
//  用户那份 1.8.0 的 `.ips`，主线程栈是：
//
//      UIApplication _firstCommitBlock
//        → CA::Transaction::commit
//          → _UIHostingView.layoutSubviews
//            → SwiftUI ViewGraphRootValueUpdater.render
//              → Update.dispatchActions
//                → （我们的代码）
//                  → NSManagedObjectContext.performAndWait
//                    → sqlite3_step
//                      → _platform_memmove        ← 正在拷那 13 MB blob
//
//  来源就是 `ProjectImageViews`：`InventoryManager` 是 `@MainActor`，
//  `fetchProjectDisplayThumbnail` / `fetchProjectThumbnailData` 都是**主线程同步
//  SwiftData fetch**。首屏一次渲染 10 个 row，每个 row 至少一次主线程读库；
//  老数据（`displayThumbnail == nil`）还会掉进第二条 fallback，
//  在主线程上把 13 MB 原图整个读出来。
//
//  再叠加库涨到 GB 级之后 CoreData+CloudKit 的
//  `_performPostSaveTasks:andForceFullVacuum:` 持 EXCLUSIVE 锁 —— 这些读全部排队，
//  首帧提交被拖过 scene-create 看门狗的 2.06s → `0x8BADF00D`。
//
//  ## 为什么是 actor
//
//  两个作用，缺一不可：
//
//  1. **脱离主线程**：所有 fetch 跑在独立的后台 `ModelContext` 上，主线程只等结果。
//     库再忙也只是图晚一点出来，不会挡住首帧提交。
//  2. **串行化**：actor 隔离天然保证同一时刻只有一次取图在飞。这对
//     `downsampledRawThumbnail` 尤其关键 —— 老数据还没瘦身完时，10 个 row 并发各读
//     一份 13 MB 原图就是 130 MB 瞬时峰值，正是 jetsam 的老路。串行之后峰值恒定为一份。
//
//  `ModelContext` 不是 Sendable，所以这里持有的是 `ModelContainer`（Sendable），
//  每次调用现开一个 context —— 与 `ThumbnailMigrationCoordinator` 里的后台写入同型。

import Foundation
import SwiftData
import UIKit

actor ProjectImageLoader {
    private let container: ModelContainer

    init(container: ModelContainer) {
        self.container = container
    }

    /// 列表 row 用的小图（512px JPEG，~50-100 KB）。
    func displayThumbnail(for projectId: UUID) -> Data? {
        fetchColumn(projectId: projectId, keyPath: \.displayThumbnail, event: "display_thumbnail")
    }

    /// 成品图原字节。调用方自己决定怎么解码。
    func finishedImage(for projectId: UUID) -> Data? {
        fetchColumn(projectId: projectId, keyPath: \.finishedImage, event: "finished_image")
    }

    /// 图纸原字节（拼图模式 / 详情大图）。
    func thumbnail(for projectId: UUID) -> Data? {
        fetchColumn(projectId: projectId, keyPath: \.thumbnail, event: "thumbnail")
    }

    /// 拼图模式网格（四角 / 行列 / 色号矩阵）。字节很小，但仍然走后台 —— 它总是跟
    /// `thumbnail` 一起被取，留在主线程就白白抵消了另一半的改动。
    func patternGrid(for projectId: UUID) -> BeadPatternGrid? {
        guard let data = fetchColumn(projectId: projectId, keyPath: \.patternGridData, event: "pattern_grid") else {
            return nil
        }
        return SDProjectRecord.decodePatternGrid(data, projectId: projectId)
    }

    /// 老数据没有 `displayThumbnail` 时的兜底：读原图 → 现场降级成小图。
    ///
    /// **只走 `ImageDownsampler`，永远不 `UIImage(data: raw)`** —— 后者会全分辨率解码
    /// （13 MB PNG → 30-60 MB UIImage）。`CGImageSourceCreateThumbnailAtIndex` 在 source 层
    /// 就限制尺寸，峰值 KB 级。
    ///
    /// 返回 UIImage 而不是 Data：省掉一次 JPEG encode/decode 往返，也让「原图字节」
    /// 不会流出这个 actor（调用方拿不到就不可能不小心把它存起来）。
    func downsampledRawThumbnail(for projectId: UUID) -> UIImage? {
        enter()
        defer { leave() }
        guard let raw = fetchColumn(projectId: projectId, keyPath: \.thumbnail, event: "raw_thumbnail_fallback") else {
            return nil
        }
        return ImageDownsampler.downsampleToUIImage(raw)
    }

    /// 日历格子用的成品图小图：读原字节 → 现场降级到 `maxPixelSize`。
    ///
    /// 降级放在 actor 内部而不是让调用方拿着 `Data` 自己做，是为了让**原字节不流出**这个
    /// actor —— 调用方拿不到就不可能不小心把它存进 `@State` 常驻内存。
    ///
    /// - Returns: `bytesFound` 区分「库里就没有这张图」和「有字节但解不开」。
    ///   日历只为 `projectIDsWithFinishedImage` 里的项目渲染图片分支，
    ///   所以 `bytesFound == false` 说明集合与库漂移了（删除/合并/恢复竞态留下的陈旧成员），
    ///   调用方要留日志，别静默成空格子。
    func downsampledFinishedImage(
        for projectId: UUID,
        maxPixelSize: Int
    ) -> (bytesFound: Bool, image: UIImage?) {
        enter()
        defer { leave() }
        guard let data = fetchColumn(projectId: projectId, keyPath: \.finishedImage, event: "finished_image_thumbnail") else {
            return (false, nil)
        }
        let image = ImageDownsampler.downsampleToUIImage(data, maxPixelSize: max(1, maxPixelSize))
        if image == nil {
            // 有字节但解不开 = 真正的损坏信号，而调用方只对 bytesFound == false 记日志，
            // 于是这一格会渲染成空白且零遥测。补一条。
            AppLogger.shared.error("ProjectImageLoader", "finished_image_undecodable", metadata: [
                "projectId": projectId.uuidString, "bytes": data.count
            ])
        }
        return (true, image)
    }

    // MARK: - 测试探针

    /// 供 `ProjectImageLoaderTests` 钉住「取图不在主线程」这条不变量。
    /// 一旦有人把本类改回 `@MainActor`（或把 fetch 挪回 `InventoryManager`），测试会红。
    func isCurrentlyOnMainThreadForTesting() -> Bool { Thread.isMainThread }

    /// 观测到的最大并发数。
    ///
    /// 窗口盖的是**两条降级方法**（`downsampledRawThumbnail` / `downsampledFinishedImage`），
    /// 不是全部六个公开方法 —— 纯 fetch 方法是同步 actor 方法，隔离下并发数结构上
    /// 不可能大于 1，包了也是自证命题；真正有内存代价、也真正可能被未来某次
    /// 「加个 await」破坏的，是「读原图 + 降级」这两段。
    private(set) var peakConcurrencyForTesting = 0
    private var inFlight = 0

    private func enter() {
        inFlight += 1
        if inFlight > peakConcurrencyForTesting { peakConcurrencyForTesting = inFlight }
    }
    private func leave() { inFlight -= 1 }

    // MARK: - 内部

    /// 单列投影 fetch。
    ///
    /// `propertiesToFetch` 限定单列是必须的：不限定的话，同行的其它 blob
    /// （raw thumbnail 可能是 MB 级）会跟着一起物化 —— 列表每滚一个 row 都要付这份代价。
    ///
    /// 早期写法是 `switch keyPath { ... default: break }`，而 `propertiesToFetch` 的默认值
    /// 是 `[]` = **不投影** = SELECT 全列。也就是说将来加一个 blob 列 + 一个忘记加 case 的
    /// 取值方法，就会静默物化整行 —— 正是本文件存在要防的那个回归，且无编译错误、
    /// 无测试失败、无日志。现在直接把 keyPath 传给 `propertiesToFetch`
    ///（它要的是 `[PartialKeyPath<T>]`，`KeyPath<_, Data?>` 可以直接上转），
    /// 少一个 switch 也就少一处可以漏的地方。
    private func fetchColumn(
        projectId: UUID,
        keyPath: KeyPath<SDProjectRecord, Data?>,
        event: String
    ) -> Data? {
        var descriptor = FetchDescriptor<SDProjectRecord>(
            predicate: #Predicate { $0.id == projectId }
        )
        descriptor.fetchLimit = 1
        descriptor.propertiesToFetch = [keyPath]
        do {
            let context = ModelContext(container)
            return try context.fetch(descriptor).first?[keyPath: keyPath]
        } catch {
            // 把「SwiftData 抛错」和「真的没图」分开记 —— 否则 store 损坏看起来就像无图。
            AppLogger.shared.error("ProjectImageLoader", "fetch_failed", metadata: [
                "column": event,
                "projectId": projectId.uuidString,
                "error": "\(error)"
            ])
            return nil
        }
    }
}

//
//  SharedImageManager.swift
//  BeadInventory
//
//  处理从 Share Extension 传入的图片
//

import SwiftUI
import UIKit

/// 共享图片管理器 - 用于主 App 和 Share Extension 之间传递图片
@MainActor
class SharedImageManager: ObservableObject {
    static let shared = SharedImageManager()

    /// App Group 标识符 - 需要在 Xcode 中配置
    static let appGroupIdentifier = "group.com.beadinventory.shared"

    /// 共享图片的文件名
    private let sharedImageFileName = "shared_image.jpg"

    /// 标记文件名（表示有新图片待处理）
    private let pendingFlagFileName = "pending_image"

    /// 当前待处理的共享图片
    @Published var pendingImage: UIImage?

    /// 是否有待处理的图片
    @Published var hasPendingImage: Bool = false

    private init() {}

    /// 获取 App Group 共享容器 URL
    var sharedContainerURL: URL? {
        FileManager.default.containerURL(forSecurityApplicationGroupIdentifier: Self.appGroupIdentifier)
    }

    /// 共享图片的完整路径
    var sharedImageURL: URL? {
        sharedContainerURL?.appendingPathComponent(sharedImageFileName)
    }

    /// 待处理标记文件路径
    var pendingFlagURL: URL? {
        sharedContainerURL?.appendingPathComponent(pendingFlagFileName)
    }

    // MARK: - Share Extension 使用的方法

    /// 保存图片到共享容器（由 Share Extension 调用）
    func saveSharedImage(_ image: UIImage) -> Bool {
        guard let imageURL = sharedImageURL,
              let flagURL = pendingFlagURL else {
            print("SharedImageManager: 无法获取共享容器路径")
            return false
        }

        // 分辨率原样保留（拼图模式需要它做网格识别），编码走 ProjectImageEncoder ——
        // 理由同 ScanView.generateThumbnailData：无损 PNG 是把库撑到 GB 级的根因。
        // 这里落的是 App Group 容器里的中转文件，压小同样省 Share Extension 的内存
        //（扩展的内存上限只有 ~120MB，pngData() 一张大图就可能被系统杀掉）。
        guard let imageData = ProjectImageEncoder.encode(image) else {
            print("SharedImageManager: 图片编码失败")
            return false
        }

        do {
            // 保存图片
            try imageData.write(to: imageURL)

            // 创建待处理标记文件
            try Data().write(to: flagURL)

            print("SharedImageManager: 图片已保存到共享容器")
            return true
        } catch {
            print("SharedImageManager: 保存图片失败 - \(error.localizedDescription)")
            return false
        }
    }

    // MARK: - 主 App 使用的方法

    /// 检查是否有待处理的共享图片
    func checkForPendingImage() {
        guard let flagURL = pendingFlagURL,
              let imageURL = sharedImageURL else {
            return
        }

        // 检查标记文件是否存在
        guard FileManager.default.fileExists(atPath: flagURL.path) else {
            return
        }

        // 加载图片
        if let imageData = try? Data(contentsOf: imageURL),
           let image = UIImage(data: imageData) {
            DispatchQueue.main.async {
                self.pendingImage = image
                self.hasPendingImage = true
            }
            print("SharedImageManager: 发现待处理的共享图片")
        }

        // 删除标记文件（表示已处理）
        try? FileManager.default.removeItem(at: flagURL)
    }

    /// 清除待处理的图片
    func clearPendingImage() {
        pendingImage = nil
        hasPendingImage = false

        // 清理共享容器中的文件
        if let imageURL = sharedImageURL {
            try? FileManager.default.removeItem(at: imageURL)
        }
        if let flagURL = pendingFlagURL {
            try? FileManager.default.removeItem(at: flagURL)
        }
    }

    /// 获取并消费待处理的图片
    func consumePendingImage() -> UIImage? {
        let image = pendingImage
        clearPendingImage()
        return image
    }
}

